  ["i m pleased to see you re back name"] = "Interface\\AddOns\\TurtlesEpoch\\sounds\\dryad\\shaeldryn\\quest_complete_544de826.ogg",
  ["i m so glad chief archeologist greywhisker sent for us"] = "Interface\\AddOns\\TurtlesEpoch\\sounds\\dwarf\\archaeologist_hollee\\quest_complete_f65da354.ogg",
